    /**
     * Written as escapes on purpose, exactly as the TypeScript does: tashkeel, the superscript
     * alef, tatweel and the bidi marks are all invisible, so a literal character class here
     * would look like an empty one in every editor.
     */
    private val AR_DIACRITICS = Regex("[\u064B-\u0652\u0670\u0640\u200E\u200F\u061C]")
    private val AR_HAMZA = Regex("[أإآٱ]")
    private val WHITESPACE = Regex("\\s+")

    /**
     * Folds the spellings that make an Arabic needle miss: hamza forms, ya/alef maqsura, ta
     * marbuta. The twin of `normalizeDrugText` on the web — a search that folded differently
     * here would find a different drug for the same typed word.
     *
     * `lowercase()` and not `toLowerCase()`: the latter follows the device locale, and on a
     * Turkish phone it turns every capital I into a dotless one.
     */
    fun normalize(raw: String): String =
        raw.lowercase()
            .replace(AR_DIACRITICS, "")
            .replace(AR_HAMZA, "ا")
            .replace("ى", "ي")
            .replace("ة", "ه")
            .replace("ؤ", "و")
            .replace("ئ", "ي")
            .replace(WHITESPACE, " ")
            .trim()

    /** Everything a search term may match on — built once, not per keystroke. */
    private val SEARCH_INDEX: Map<String, String> by lazy {
        val byId = CATEGORIES.associateBy { it.id }
        ALL.associate { drug ->
            val cat = byId[drug.cat]
            drug.id to normalize(
                (
                    listOf(
                        drug.name,
                        drug.genericEn,
                        drug.genericAr,
                        drug.descEn,
                        drug.descAr,
                        cat?.labelEn.orEmpty(),
                        cat?.labelAr.orEmpty(),
                    ) + drug.keywords
                ).joinToString(" ")
            )
        }
    }

    /**
     * Every whitespace-separated term must appear somewhere in the drug's text, in any order, so
     * "aug 1" and "مضاد حيوي حساسيه" both land. An empty query returns the catalog untouched.
     */
    fun search(query: String): List<CatalogDrug> {
        val q = normalize(query)
        if (q.isEmpty()) return ALL
        val terms = q.split(" ").filter { it.isNotEmpty() }
        return ALL.filter { drug ->
            val stack = SEARCH_INDEX[drug.id].orEmpty()
            terms.all { stack.contains(it) }
        }
    }

    fun categoryLabel(catId: String, arabic: Boolean): String {
        val cat = CATEGORIES.firstOrNull { it.id == catId } ?: return ""
        return if (arabic) cat.labelAr else cat.labelEn
    }
